INSERT INTO meal_recipes (id, name, description, instructions, servings, calories_per_serving, protein_g, fat_g, carb_g, goal_tags, serving_notes, tips, expert_advice, suggested_combo, created_at, updated_at) VALUES ('recipe-mi-cay-chay-2', 'Mì cay chay', 'Mì cay chay nóng hổi, vị cay thơm cho bữa ăn ngày lạnh', 'Chưa có hướng dẫn chi tiết.', 1, 0, 0, 0, 0, NULL, 'Cho mì, nấm, rau các loại vào nồi nước dùng nấu 2 phút, rắc rau quế và ngò gai cắt nhỏ lên trên. Múc ra tô, thêm tàu hũ ky chiên giòn vào, dùng nóng.', 'Xào thịt bò chay và cá viên cho thấm vị, khi ăn sẽ thơm ngon hơn.Cho mì hàn quốc trực tiếp vào nồi nước dùng giúp mì thấm gia vị.Dùng hạt nêm Aji-ngon® Nấm giúp món ăn ngọt thanh mà vẫn đậm đà.', NULL, NULL, '2026-08-07T22:02:58.523Z', '2026-08-07T22:02:58.523Z');
